mapper.select:


    p.del_flag = '0'

        and p.paper_code like concat('%', #{paperCode}, '%')


        and p.paper_name like concat('%', #{paperName}, '%')


        and p.paper_mode = #{paperMode}


        and p.status = #{status}


order by p.create_time desc

mapper.update:
update jc_edu_paper
paper_name = #{paperName}, total_score = #{totalScore}, pass_score = #{passScore}, duration_min = #{durationMin}, remark = #{remark}, update_by = #{updateBy}, update_time = now()
where paper_id = #{paperId}
